(5763448, 837710, 25355, '<td valign="top">Probably a Sydney-sider. My mother used to collect them when she was a growing up there.</td>', 'Probably a Sydney-sider. My mother used to collect them when she was a growing up there.', '2009-12-10 21:24:58.000000', NULL, 1),
(5763526, 838485, 80859, '<td valign="top">lol...  for a split second, i thought that was a real bug!</td>', 'lol...  for a split second, i thought that was a real bug!', '2009-12-10 23:25:53.000000', NULL, 1),
(5763527, 838173, 80859, '<td valign="top">absolutely amazing....10</td>', 'absolutely amazing....10', '2009-12-10 23:27:50.000000', NULL, 1),
(5763528, 838141, 80859, '<td valign="top">great shot!  very unique and interesting perspective</td>', 'great shot!  very unique and interesting perspective', '2009-12-10 23:29:04.000000', NULL, 1),
(5763555, 838337, 108580, '<td valign="top">Wonderful shot, detail on almost the whole body which means excellent DOF control and lighting. Great bokeh. The wing hiding the eye is a bit detracting. Bumped to a 7.</td>', 'Wonderful shot, detail on almost the whole body which means excellent DOF control and lighting. Great bokeh. The wing hiding the eye is a bit detracting. Bumped to a 7.', '2009-12-11 00:14:30.000000', NULL, 1),
(5763558, 838366, 108580, '<td valign="top">Had a second look. I started with a 6 but it deserves more for excellent focus <u>and</u> composition. I also went with a smaller bug and nicer floral composition. Not everything macro has to be in your face. See then if you can pick my entry... Bokeh is superb. Bumped to 8.</td>', 'Had a second look. I started with a 6 but it deserves more for excellent focus and composition. I also went with a smaller bug and nicer floral composition. Not everything macro has to be in your face. See then if you can pick my entry... Bokeh is superb. Bumped to 8.', '2009-12-11 00:17:18.000000', NULL, 1),
(5763559, 838506, 108580, '<td valign="top">Almost perfect shot. I love the primary browns. Good lighting on the central subject. I would have cropped out the bottom right green. I also went with a smaller subject <u>and</u> a nicer overall composition. Not everything macro has to be in your face.</td>', 'Almost perfect shot. I love the primary browns. Good lighting on the central subject. I would have cropped out the bottom right green. I also went with a smaller subject and a nicer overall composition. Not everything macro has to be in your face.', '2009-12-11 00:18:00.000000', NULL, 1),
(5763564, 838086, 108580, '<td valign="top">Great shot great bokeh. Crisp focus on eye meaning good DOF control. Catchlight a bit distracting and larger than it needs to be.</td>', 'Great shot great bokeh. Crisp focus on eye meaning good DOF control. Catchlight a bit distracting and larger than it needs to be.', '2009-12-11 00:19:50.000000', NULL, 1),
(5763567, 837831, 108580, '<td valign="top">Very cute, good focus and comp. Unusual side of the bug you rarely see. Bokeh (sky) well controlled.</td>', 'Very cute, good focus and comp. Unusual side of the bug you rarely see. Bokeh (sky) well controlled.', '2009-12-11 00:20:50.000000', NULL, 1),
(5763645, 838249, 56579, '<td valign="top">Wish it had a bit more DOF</td>', 'Wish it had a bit more DOF', '2009-12-11 02:59:41.000000', NULL, 1),
(5763646, 838361, 56579, '<td valign="top">Looks slightly under exposed, wish it was a bit sharper on the lady bugs face.</td>', 'Looks slightly under exposed, wish it was a bit sharper on the lady bugs face.', '2009-12-11 03:03:05.000000', NULL, 1),
(5763648, 838096, 110041, '<td valign="top">That is one of the scariest things''s I''ve ever seen! what the hell is it?</td>', 'That is one of the scariest things''s I''ve ever seen! what the hell is it?', '2009-12-11 03:08:40.000000', NULL, 1),
(5763664, 838173, 65592, '<td valign="top">I expect this stunning image (by roz?) to ribbon. Just to add something, i think that you should consider focus stacking to get a higher dof, not with moving subjects...just keep it in mind for still subjects. Congratulations on this wonderfull picture.9</td>', 'I expect this stunning image (by roz?) to ribbon. Just to add something, i think that you should consider focus stacking to get a higher dof, not with moving subjects...just keep it in mind for still subjects. Congratulations on this wonderfull picture.9', '2009-12-11 03:54:17.000000', NULL, 1),
(5763665, 837451, 65592, '<td valign="top">My favorite for the blue ribbon. Love composition and lighting. Just wish a little extra dof to get the head in sharp focus. Congratulations on this stunning image.</td>', 'My favorite for the blue ribbon. Love composition and lighting. Just wish a little extra dof to get the head in sharp focus. Congratulations on this stunning image.', '2009-12-11 03:54:33.000000', NULL, 1),
(5763666, 837710, 65592, '<td valign="top">Stunning macro. Love the light.9</td>', 'Stunning macro. Love the light.9', '2009-12-11 03:54:44.000000', NULL, 1),
(5763668, 838169, 37252, '<td valign="top">Sorry but the lack of focus makes me give this a 4</td>', 'Sorry but the lack of focus makes me give this a 4', '2009-12-11 03:55:13.000000', NULL, 1),
(5763669, 838509, 65592, '<td valign="top">Love colors and composition. Good bokeh also. Hope this one to be on the front page.</td>', 'Love colors and composition. Good bokeh also. Hope this one to be on the front page.', '2009-12-11 03:56:09.000000', NULL, 1),
(5763670, 838218, 37252, '<td valign="top">Sorry but the poor focus makes me give this a 4</td>', 'Sorry but the poor focus makes me give this a 4', '2009-12-11 03:57:44.000000', NULL, 1),
(5763671, 837246, 37252, '<td valign="top">Cute shoehorn, but I cannot in good conscious give this a very high score with all the other entries meeting the true idea of the challenge.</td>', 'Cute shoehorn, but I cannot in good conscious give this a very high score with all the other entries meeting the true idea of the challenge.', '2009-12-11 03:58:40.000000', NULL, 1),
(5763672, 838076, 65592, '<td valign="top">Love the color contrast. This is a pleasant image to look at.</td>', 'Love the color contrast. This is a pleasant image to look at.', '2009-12-11 03:58:46.000000', NULL, 1);
