(5763673, 837473, 65592, '<td valign="top">Amazing insect, wish the background to be more appealing to make this incredible bug shine.</td>', 'Amazing insect, wish the background to be more appealing to make this incredible bug shine.', '2009-12-11 04:00:30.000000', NULL, 1),
(5763679, 838165, 65592, '<td valign="top">Really difficult exposure here, strong side light on the subject and stamen with a dark background. The bug seems overexposed partially and also i miss a little sharpness on it (not sure about this). Love the background and the light through the stamens.</td>', 'Really difficult exposure here, strong side light on the subject and stamen with a dark background. The bug seems overexposed partially and also i miss a little sharpness on it (not sure about this). Love the background and the light through the stamens.', '2009-12-11 04:10:51.000000', NULL, 1),
